      SUBROUTINE RDENDC---- PRINT NUMBER OF ERROR MESSAGES GENERATEDC-------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'IOUNIT.CIN'C-------------------------------------------------------------------      IF (NWARN .NE. 0 .OR. NFAIL .NE. 0) THEN        WRITE (NOUT,910)        WRITE (NOUT,920) NWARN        WRITE (NOUT,930) NFAIL        WRITE (NOUT,940)      ENDIF      RETURNC-------------------------------------------------------------------  910 FORMAT('1**************************************')  920 FORMAT(' * NUMBER OF WARNING MESSAGES =',I6,' *')  930 FORMAT(' * NUMBER OF FATAL ERRORS     =',I6,' *')  940 FORMAT(' **************************************')C-------------------------------------------------------------------      END